window.AUTH=window.AUTH||{};window.AUTH["22-10"]={"d":"22-10","id":"2022/22-10","n":"Dubin v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner David Dubin","date":"2022-12-23","url":"https://www.supremecourt.gov/DocketPDF/22/22-10/250824/20221223152000629_22-10%20ts.pdf","side":"pet","n":54},{"k":"respondent","label":"Brief of respondent United States","date":"2023-01-23","url":"https://www.supremecourt.gov/DocketPDF/22/22-10/253000/20230123185001242_Dubin%2022-10.pdf","side":"res","n":71},{"k":"reply","label":"Reply of petitioner David Dubin","date":"2023-02-16","url":"https://www.supremecourt.gov/DocketPDF/22/22-10/254992/20230216154033125_22-10rb_pdfa.pdf","side":"pet","n":35}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r34_p86b.pdf","tr":true,"items":[{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"op":1,"sum":"The Court held that the jury instructions failed to convey that the federal document law required a \"consciousness of wrongdoing\" for conviction. There was nothing inherently corrupt in ordering employees to destroy documents, even if the aim was to keep the documents from the government.","sumSrc":"Oyez","by":{"0":"2"}},{"t":"case","label":"Bailey v. United States","cite":"516 U.S. 137","y":1995,"id":"1995/94-7448","sc":1,"op":6,"sum":"The proximity and accessibility test for \"use\" is so broad that no independent role remains for \"carry.\" \"Use\" in Section 924(c)(1) requires more than proximity and accessibility that might embolden a defendant. It requires active employment of the firearm by the defendant, making the firearm an operative factor in relation to the predicate offense.","sumSrc":"Oyez","by":{"0":"18, 19, 27","1":"12","2":"15"}},{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"sum":"In a 6-3 vote, the Court held that Begay's DWI convictions did not qualify as \"violent felonies\" because they were too different from the violent felony examples provided by Congress in the Armed Career Criminal Act (such as burglary, arson and extortion). Therefore, Begay should not have been subject to the mandatory sentencing hike.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"ar":2,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"op":3,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Cleveland v. United States","cite":"531 U.S. 12","y":2000,"id":"2000/99-804","sc":1,"sum":"The Court held that State and municipal licenses in general, and Louisiana's video poker licenses in particular, do not rank as \"property,\" for purposes of federal law, in the hands of the official licensor.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Commonwealth v. Brown","cite":"21 S.E. 357","y":1895,"court":"Va.","url":"https://www.courtlistener.com/c/S.E./21/357/","by":{"0":"41"}},{"t":"case","label":"People ex rel. Failing v. Hwy. Comm’rs of Town of Palatine","cite":"53 Barb. 70","y":1869,"court":"N.Y. Gen. Term.","url":"https://www.courtlistener.com/c/Barb./53/70/","by":{"0":"41"}},{"t":"case","label":"Flores-Figueroa v. United States","cite":"556 U.S. 646","y":2009,"id":"2008/08-108","sc":1,"op":4,"ar":2,"sum":"The Court found that in order to prove aggravated identity theft, the government needs to prove that the defendant knew that the identification he possessed belonged to another person.","sumSrc":"Oyez","by":{"0":"28","1":"26, 30, 31","2":"14"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"sum":"The Court held that the Eleventh Circuit Court of Appeals was bound by Florida state law in considering a felony battery charge.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"op":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Kelly v. United States","cite":"140 S. Ct. 1565","y":2020,"id":"2019/18-1059","sc":1,"sum":"The Court held that Baroni and Kelly, who executed the New Jersey “Bridgegate” political retribution scheme against Fort Lee’s mayor, did not violate the federal-program fraud or wire fraud laws because they did not aim to obtain money or property from the federal Port Authority.","sumSrc":"Oyez","by":{"0":"2"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"op":4,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Marinello v. United States","cite":"138 S. Ct. 1101","y":2018,"id":"2017/16-1144","sc":1,"op":6,"ar":4,"sum":"The Court held that a conviction under 26 U.S.C. § 7212(a) for corruptly endeavoring to obstruct or impede the due administration of the tax laws requires proof that the defendant acted with knowledge of a pending Internal Revenue Service action.","sumSrc":"Oyez","by":{"0":"2, 34, 39","2":"3"}},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"op":4,"sum":"The Court held that, for the purpose of federal bribery statutes, an “official act” is a decision or action on a question, matter, cause, suit, proceeding, or controversy that involves a specific exercise of formal governmental power.","sumSrc":"Oyez","by":{"0":"2, 37, 38, 39","2":"21"}},{"t":"case","label":"Muscarello v. United States","cite":"524 U.S. 125","y":1998,"id":"1997/96-1654","sc":1,"sum":"The Court held that the phrase \"carries a firearm\" applies to a person who knowingly possesses and conveys firearms in a vehicle, including in the locked glove compartment or trunk of a car, which the person accompanies.","sumSrc":"Oyez","by":{"0":"20","1":"11, 12, 14, 30"}},{"t":"case","label":"People v. Carstensen","cite":"420 P.2d 820","y":1966,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/420/820/","by":{"0":"25"}},{"t":"case","label":"People v. Friederich","cite":"185 P. 657","y":1919,"court":"Colo.","url":"https://www.courtlistener.com/c/P./185/657/","by":{"0":"41"}},{"t":"case","label":"Rouleau v. Avrach","cite":"233 So. 2d 1","y":1970,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/233/1/","by":{"0":"41"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"sum":"The Court held that the former CEO of Enron received a fair trial before an impartial jury, and that the federal law that makes it a crime to deprive someone of a fair and honest trial only applies to bribery and kickback schemes.","sumSrc":"Oyez","by":{"0":"37, 38","2":"21-22"}},{"t":"case","label":"Smith v. United States","cite":"508 U.S. 223","y":1993,"id":"1992/91-8674","sc":1,"op":3,"sum":"Authored by Justice Sandra Day O'Connor, the Court ruled that a criminal who trades his or her firearm for drugs \"uses\" it \"during and in relation to . . . [a] drug trafficking crime,\" which is within the bounds of the sentence enhancement. Justice O'Connor wrote that Congress intended to make the word \"use\" as broad as possible when it wrote the law.","sumSrc":"Oyez","by":{"0":"19, 20, 21, 43","1":"10-14, 30","2":"3, 4"}},{"t":"case","label":"State v. Dunn","cite":"267 So. 2d 193","y":1972,"court":"La.","url":"https://www.courtlistener.com/c/So.%202d/267/193/","by":{"0":"25"}},{"t":"case","label":"State v. Harper","cite":"785 P.2d 1341","y":1990,"court":"Kan.","url":"https://www.courtlistener.com/c/P.2d/785/1341/","by":{"0":"25"}},{"t":"case","label":"State v. Thibeault","cite":"402 A.2d 445","y":1979,"court":"Me.","url":"https://www.courtlistener.com/c/A.2d/402/445/","by":{"0":"25"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Torres v. Lynch","cite":"578 U.S. 452","y":2016,"id":"2015/14-1096","sc":1,"sum":"The Court determined that a state offense may constitute an aggravated felony for the purpose of the removal of a permanent resident when it includes all the elements of the federal statute with the exception of the interstate commerce element.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"United States v. Berroa","cite":"856 F.3d 141","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/856/141/","op":3,"by":{"0":"38, 43"}},{"t":"case","label":"United States v. Croft","cite":"2022 WL 1652742","y":2022,"court":"5th Cir. May 24","sum":"Recognizing that “our en banc court [in Dubin] adopted the panel’s opinion”.","sumSrc":"brief:0","by":{"0":"11"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36, 42"}},{"t":"case","label":"United States v. Mahmood","cite":"820 F.3d 177","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/820/177/","by":{"0":"10"}},{"t":"case","label":"United States v. Medlock","cite":"792 F.3d 700","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/792/700/","op":2,"by":{"0":"11, 21"}},{"t":"case","label":"United States v. Michael","cite":"882 F.3d 624","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/882/624/","op":5,"by":{"0":"21, 22","2":"4, 5"}},{"t":"case","label":"United States v. Miller","cite":"734 F.3d 530","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/734/530/","by":{"0":"43"}},{"t":"case","label":"United States v. Spears","cite":"729 F.3d 753","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/729/753/","op":4,"by":{"0":"33, 43"}},{"t":"case","label":"United States v. Taylor","cite":"142 S. Ct. 2015","y":2022,"id":"2021/20-1459","sc":1,"sum":"Attempted Hobbs Act robbery does not qualify as a “crime of violence” under 18 U. S. C. §924(c)(3)(A) because no element of the offense requires proof that the defendant used, attempted to use, or threatened to use force.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24","2":"8"}},{"t":"case","label":"Van Buren v. United States","cite":"141 S. Ct. 1648","y":2021,"id":"2020/19-783","sc":1,"op":1,"ar":4,"sum":"An individual “exceeds authorized access” under the Computer Fraud and Abuse Act of 1986, 18 U. S. C. §1030(a)(2), when he accesses a computer with authorization but then obtains information located in particular areas of the computer—such as files, folders, or databases—that are off-limits to him.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"2, 14, 20, 39","1":"25, 30","2":"3"}},{"t":"case","label":"Weyerhaeuser Co. v. U.S. Fish & Wildlife Serv.","cite":"139 S. Ct. 361","y":2018,"id":"2018/17-71","sc":1,"sum":"An area is eligible for designation as “critical habitat” under the Endangered Species Act of 1973 only if it is habitat for the listed species; and the Secretary of the Interior’s decision not to exclude an area from critical habitat under 16 U. S. C. §1533(b)(2) is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"op":2,"ar":4,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"2, 29, 30","1":"13"}},{"t":"usc","label":"18 U.S.C. § 1028","url":"https://www.law.cornell.edu/uscode/text/18/1028","subs":["(a)(7)","(a)","(a)(6)","(d)(7)"],"stext":{"head":"§1028. Fraud and related activity in connection with identification documents, authentication features, and information","paras":[[0,"(a) Whoever, in a circumstance described in subsection (c) of this section—"],[1,"(1) knowingly and without lawful authority produces an identification document, authentication feature, or a false identification document;"],[1,"(2) knowingly transfers an identification document, authentication feature, or a false identification document knowing that such document or feature was stolen or produced without lawful authority;"],[1,"(3) knowingly possesses with intent to use unlawfully or transfer unlawfully five or more identification documents (other than those issued lawfully for the use of the possessor), authentication features, or false identification documents;"],[1,"(4) knowingly possesses an identification document (other than one issued lawfully for the use of the possessor), authentication feature, or a false identification document, with the intent such document or feature be used to defraud the United States;"],[1,"(5) knowingly produces, transfers, or possesses a document-making implement or authentication feature with the intent such document-making implement or authentication feature will be used in the production of a false identification document or another document-making implement or authentication feature which will be so used;"],[1,"(6) knowingly possesses an identification document or authentication feature that is or appears to be an identification document or authentication feature of the United States or a sponsoring entity of an event designated as a special event of national significance which is stolen or produced without lawful authority knowing that such document or feature was stolen or produced without such authority;"],[1,"(7) knowingly transfers, possesses, or uses, without lawful authority, a means of identification of another person with the intent to commit, or to aid or abet, or in connection with, any unlawful activity that constitutes a violation of Federal law, or that constitutes a felony under any applicable State or local law; or"],[1,"(8) knowingly traffics in false or actual authentication features for use in false identification documents, document-making implements, or means of identification;"],[0,"shall be punished as provided in subsection (b) of this section."],[0,"(b) The punishment for an offense under subsection (a) of this section is—"],[1,"(1) except as provided in paragraphs (3) and (4), a fine under this title or imprisonment for not more than 15 years, or both, if the offense is—"],[2,"(A) the production or transfer of an identification document, authentication feature, or false identification document that is or appears to be—"],[3,"(i) an identification document or authentication feature issued by or under the authority of the United States; or"],[3,"(ii) a birth certificate, or a driver's license or personal identification card;"],[2,"(B) the production or transfer of more than five identification documents, authentication features, or false identification documents;"],[2,"(C) an offense under paragraph (5) of such subsection; or"],[2,"(D) an offense under paragraph (7) of such subsection that involves the transfer, possession, or use of 1 or more means of identification if, as a result of the offense, any individual committing the offense obtains anything of value aggregating $1,000 or more during any 1-year period;"],[1,"(2) except as provided in paragraphs (3) and (4), a fine under this title or imprisonment for not more than 5 years, or both, if the offense is—"],[2,"(A) any other production, transfer, or use of a means of identification, an identification document,,1 authentication feature, or a false identification document; or"],[2,"(B) an offense under paragraph (3) or (7) of such subsection;"],[1,"(3) a fine under this title or imprisonment for not more than 20 years, or both, if the offense is committed—"],[2,"(A) to facilitate a drug trafficking crime (as defined in section 929(a)(2));"],[2,"(B) in connection with a crime of violence (as defined in section 924(c)(3)); or"],[2,"(C) after a prior conviction under this section becomes final;"],[1,"(4) a fine under this title or imprisonment for not more than 30 years, or both, if the offense is committed to facilitate an act of domestic terrorism (as defined under section 2331(5) of this title) or an act of international terrorism (as defined in section 2331(1) of this title);"],[1,"(5) in the case of any offense under subsection (a), forfeiture to the United States of any personal property used or intended to be used to commit the offense; and"],[1,"(6) a fine under this title or imprisonment for not more than one year, or both, in any other case."],[0,"(c) The circumstance referred to in subsection (a) of this section is that—"],[1,"(1) the identification document, authentication feature, or false identification document is or appears to be issued by or under the authority of the United States or a sponsoring entity of an event designated as a special event of national significance or the document-making implement is designed or suited for making such an identification document, authentication feature, or false identification document;"],[1,"(2) the offense is an offense under subsection (a)(4) of this section; or"],[1,"(3) either—"],[2,"(A) the production, transfer, possession, or use prohibited by this section is in or affects interstate or foreign commerce, including the transfer of a document by electronic means; or"],[2,"(B) the means of identification, identification document, false identification document, or document-making implement is transported in the mail in the course of the production, transfer, possession, or use prohibited by this section."],[0,"(d) In this section and section 1028A—"],[1,"(1) the term \"authentication feature\" means any hologram, watermark, certification, symbol, code, image, sequence of numbers or letters, or other feature that either individually or in combination with another feature is used by the issuing authority on an identification document, document-making implement, or means of identification to determine if the document is counterfeit, altered, or otherwise falsified;"],[1,"(2) the term \"document-making implement\" means any implement, impression, template, computer file, computer disc, electronic device, or computer hardware or software, that is specifically configured or primarily used for making an identification document, a false identification document, or another document-making implement;"],[1,"(3) the term \"identification document\" means a document made or issued by or under the authority of the United States Government, a State, political subdivision of a State, a sponsoring entity of an event designated as a special event of national significance, a foreign government, political subdivision of a foreign government, an international governmental or an international quasi-governmental organization which, when completed with information concerning a particular individual, is of a type intended or commonly accepted for the purpose of identification of individuals;"],[1,"(4) the term \"false identification document\" means a document of a type intended or commonly accepted for the purposes of identification of individuals that—"],[2,"(A) is not issued by or under the authority of a governmental entity or was issued under the authority of a governmental entity but was subsequently altered for purposes of deceit; and"],[2,"(B) appears to be issued by or under the authority of the United States Government, a State, a political subdivision of a State, a sponsoring entity of an event designated by the President as a special event of national significance, a foreign government, a political subdivision of a foreign government, or an international governmental or quasi-governmental organization;"],[1,"(5) the term \"false authentication feature\" means an authentication feature that—"],[2,"(A) is genuine in origin, but, without the authorization of the issuing authority, has been tampered with or altered for purposes of deceit;"],[2,"(B) is genuine, but has been distributed, or is intended for distribution, without the authorization of the issuing authority and not in connection with a lawfully made identification document, document-making implement, or means of identification to which such authentication feature is intended to be affixed or embedded by the respective issuing authority; or"],[2,"(C) appears to be genuine, but is not;"],[1,"(6) the term \"issuing authority\"—"],[2,"(A) means any governmental entity or agency that is authorized to issue identification documents, means of identification, or authentication features; and"],[2,"(B) includes the United States Government, a State, a political subdivision of a State, a sponsoring entity of an event designated by the President as a special event of national significance, a foreign government, a political subdivision of a foreign government, or an international government or quasi-governmental organization;"],[1,"(7) the term \"means of identification\" means any name or number that may be used, alone or in conjunction with any other information, to identify a specific individual, including any—"],[2,"(A) name, social security number, date of birth, official State or government issued driver's license or identification number, alien registration number, government passport number, employer or taxpayer identification number;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1028?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1028. Fraud and related activity in connection with identification documents, authentication features, and information","tname":"Crimes and Criminal Procedure","by":{"0":"16, 35, 36","1":"19, 20, 20, 34, 20","2":"20, 21"}},{"t":"usc","label":"18 U.S.C. § 1028A","url":"https://www.law.cornell.edu/uscode/text/18/1028A","subs":["(a)(1)","(b)","(c)","(a)(2)","(b)(1)"],"stext":{"head":"§1028A. Aggravated identity theft","paras":[[0,"(a) Offenses.—"],[1,"(1) In general.—Whoever, during and in relation to any felony violation enumerated in subsection (c), knowingly transfers, possesses, or uses, without lawful authority, a means of identification of another person shall, in addition to the punishment provided for such felony, be sentenced to a term of imprisonment of 2 years."],[1,"(2) Terrorism offense.—Whoever, during and in relation to any felony violation enumerated in section 2332b(g)(5)(B), knowingly transfers, possesses, or uses, without lawful authority, a means of identification of another person or a false identification document shall, in addition to the punishment provided for such felony, be sentenced to a term of imprisonment of 5 years."],[0,"(b) Consecutive Sentence.—Notwithstanding any other provision of law—"],[1,"(1) a court shall not place on probation any person convicted of a violation of this section;"],[1,"(2) except as provided in paragraph (4), no term of imprisonment imposed on a person under this section shall run concurrently with any other term of imprisonment imposed on the person under any other provision of law, including any term of imprisonment imposed for the felony during which the means of identification was transferred, possessed, or used;"],[1,"(3) in determining any term of imprisonment to be imposed for the felony during which the means of identification was transferred, possessed, or used, a court shall not in any way reduce the term to be imposed for such crime so as to compensate for, or otherwise take into account, any separate term of imprisonment imposed or to be imposed for a violation of this section; and"],[1,"(4) a term of imprisonment imposed on a person for a violation of this section may, in the discretion of the court, run concurrently, in whole or in part, only with another term of imprisonment that is imposed by the court at the same time on that person for an additional violation of this section, provided that such discretion shall be exercised in accordance with any applicable guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28."],[0,"(c) Definition.—For purposes of this section, the term \"felony violation enumerated in subsection (c)\" means any offense that is a felony violation of—"],[1,"(1) section 641 (relating to theft of public money, property, or rewards 1), section 656 (relating to theft, embezzlement, or misapplication by bank officer or employee), or section 664 (relating to theft from employee benefit plans);"],[1,"(2) section 911 (relating to false personation of citizenship);"],[1,"(3) section 922(a)(6) (relating to false statements in connection with the acquisition of a firearm);"],[1,"(4) any provision contained in this chapter (relating to fraud and false statements), other than this section or section 1028(a)(7);"],[1,"(5) any provision contained in chapter 63 (relating to mail, bank, and wire fraud);"],[1,"(6) any provision contained in chapter 69 (relating to nationality and citizenship);"],[1,"(7) any provision contained in chapter 75 (relating to passports and visas);"],[1,"(8) section 523 of the Gramm-Leach-Bliley Act (15 U.S.C. 6823) (relating to obtaining customer information by false pretenses);"],[1,"(9) section 243 or 266 of the Immigration and Nationality Act (8 U.S.C. 1253 and 1306) (relating to willfully failing to leave the United States after deportation and creating a counterfeit alien registration card);"],[1,"(10) any provision contained in chapter 8 of title II of the Immigration and Nationality Act (8 U.S.C. 1321 et seq.) (relating to various immigration offenses); or"],[1,"(11) section 208, 811, 1107(b), 1128B(a), or 1632 of the Social Security Act (42 U.S.C. 408, 1011, 1307(b), 1320a–7b(a), and 1383a) (relating to false statements relating to programs under the Act)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1028A?type=usc&year=mostrecent&link-type=html"},"op":11,"ar":1,"head":"§1028A. Aggravated identity theft","tname":"Crimes and Criminal Procedure","by":{"0":"passim, passim, 6, 32, 5","1":"20, 20, 20, 20, 20, 20, 20","2":"1-8, 10-11, 13-14, 16-22, 5, 6, 11, 15"}},{"t":"usc","label":"18 U.S.C. § 1030","url":"https://www.law.cornell.edu/uscode/text/18/1030","subs":["(a)(2)","(e)(6)"],"by":{"0":"20, 20"}},{"t":"usc","label":"18 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/18/1341","by":{"0":"34"}},{"t":"usc","label":"18 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/18/1343","by":{"0":"33, 34, 38"}},{"t":"usc","label":"18 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/18/1344","stext":{"head":"§1344. Bank fraud","paras":[[0,"Whoever knowingly executes, or attempts to execute, a scheme or artifice—"],[1,"(1) to defraud a financial institution; or"],[1,"(2) to obtain any of the moneys, funds, credits, assets, securities, or other property owned by, or under the custody or control of, a financial institution, by means of false or fraudulent pretenses, representations, or promises;"],[0,"shall be fined not more than $1,000,000 or imprisoned not more than 30 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1344?type=usc&year=mostrecent&link-type=html"},"head":"§1344. Bank fraud","tname":"Crimes and Criminal Procedure","by":{"0":"33, 38","2":"7"}},{"t":"usc","label":"18 U.S.C. § 1347","url":"https://www.law.cornell.edu/uscode/text/18/1347","subs":["(a)(2)","(a)"],"stext":{"head":"§1347. Health care fraud","paras":[[0,"(a) Whoever knowingly and willfully executes, or attempts to execute, a scheme or artifice—"],[1,"(1) to defraud any health care benefit program; or"],[1,"(2) to obtain, by means of false or fraudulent pretenses, representations, or promises, any of the money or property owned by, or under the custody or control of, any health care benefit program,"],[0,"in connection with the delivery of or payment for health care benefits, items, or services, shall be fined under this title or imprisoned not more than 10 years, or both. If the violation results in serious bodily injury (as defined in section 1365 of this title), such person shall be fined under this title or imprisoned not more than 20 years, or both; and if the violation results in death, such person shall be fined under this title, or imprisoned for any term of years or for life, or both."],[0,"(b) With respect to violations of this section, a person need not have actual knowledge of this section or specific intent to commit a violation of this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1347?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§1347. Health care fraud","tname":"Crimes and Criminal Procedure","by":{"0":"32, 38","1":"2, 3, 16","2":"5, 7"}},{"t":"usc","label":"18 U.S.C. § 1519","url":"https://www.law.cornell.edu/uscode/text/18/1519","by":{"0":"29"}},{"t":"law","label":"Identity Theft Penalty Enhancement Act, Pub. L. No. 108-275","url":"https://www.govinfo.gov/link/plaw/108/public/275","by":{"0":"5, 28, 29","1":"11"}},{"t":"case","label":"Bates v. United States","cite":"522 U.S. 23","y":1997,"id":"1997/96-7185","sc":1,"sum":"The Court held that the specific intent to injure or defraud someone, whether the United States or another, is not an element of the misapplication of funds proscribed by section 1097(a).","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"(III) Cases—Continued: Birchfield v. North Dakota","cite":"579 U.S. 438","y":2016,"id":"2015/14-1468","sc":1,"op":3,"sum":"The Court determined that warrantless blood tests incident to an arrest for drunk driving violate the Fourth Amendment, but warrantless breath tests incident to an arrest for drunk driving do not.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"op":3,"sum":"The Court held that 18 U.S.C. Section 924(c)(1)(A)(iii) does not require proof of intent to discharge a firearm in order to enhance a sentence.","sumSrc":"Oyez","by":{"1":"11, 12"}},{"t":"case","label":"DePierre v. United States","cite":"564 U.S. 70","y":2011,"id":"2010/09-1533","sc":1,"sum":"The Court held that the term \"cocaine base\" encompasses every form of cocaine that is classified chemically as a base.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Florida v. Jardines","cite":"569 U.S. 1","y":2013,"id":"2012/11-564","sc":1,"sum":"The Court found that a police officer and narcotic-sniffing dog entering the porch of a home constitutes a search and, without a warrant, is a violation of the Fourth Amendment.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Fulton v. City of Philadelphia","cite":"141 S. Ct. 1868","y":2021,"id":"2020/19-123","sc":1,"op":1,"sum":"Philadelphia’s refusal to contract with Catholic Social Services for the provision of foster care services unless CSS agrees to certify same-sex couples as foster parents violates the Free Exercise Clause of the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23, 24"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"34, 35"}},{"t":"case","label":"Lawson v. FMR LLC","cite":"571 U.S. 429","y":2014,"id":"2013/12-3","sc":1,"sum":"The Court held that the whistleblower-protection section of the Sarbanes-Oxley Act applies to privately-employed individuals.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"op":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"1":"36","2":"4, 21"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"1":"11"}},{"t":"case","label":"Ocasio v. United States","cite":"578 U.S. 282","y":2016,"id":"2015/14-361","sc":1,"sum":"The Court determined that a conspiracy to commit extortion can involve the purported victims of the extortion as members of the conspiracy.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Oncale v. Sundowner Offshore Services, Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"sum":"The Court held that while Title VII does not prohibit all verbal or physical harassment in the workplace, it does bar all forms of discrimination \"because of\" sex. Such discrimination, whether motivated by sexual desire or not, is actionable so long at it places its victim in an objectively disadvantageous working condition, regardless of the victim's gender.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Rosemond v. United States","cite":"572 U.S. 65","y":2014,"id":"2013/12-895","sc":1,"sum":"The Court held that the state must prove that an individual intended to commit or assist in committing a firearm-related offense in a drug trafficking case to be charged with offenses related to the firearm.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Schmuck v. United States","cite":"489 U.S. 705","y":1989,"id":"1988/87-6431","sc":1,"sum":"Petitioner used-car distributor was charged with multiple counts of mail fraud. The indictment alleged that he purchased used cars, rolled back their odometers, and sold them to Wisconsin retail dealers at prices artificially inflated by the low-mileage readings, and that the unwitting dealers, relying on the altered readings, resold the cars to customers at inflated prices, consummating the transactions by mailing …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32","2":"16"}},{"t":"case","label":"Trainmen v. Baltimore & Ohio R.R.","cite":"331 U.S. 519","y":1947,"id":"scdb/1946-111","sc":1,"op":2,"sum":"1. Under § 17 (11) of the Interstate Commerce Act, as amended by the Transportation Act of 1940, a union duly designated as the representative of employees of a railroad is given an absolute right, within the meaning of Rule 24 (a) (1) of the Federal Rules of Civil Procedure, to intervene in a suit brought under § 16 (12) to enjoin the railroad and its employees from violating an order of the Interstate Commerce …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24, 25","2":"11"}},{"t":"case","label":"Travelers Indemnity Co. v. Bailey","cite":"557 U.S. 137","y":2009,"id":"2008/08-295","sc":1,"sum":"The Court held that federal bankruptcy courts have jurisdiction to enter orders beyond matters directly related to the execution of a debtor's estate.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"United States v. Abdelshafi","cite":"592 F.3d 602","y":2010,"url":"https://www.courtlistener.com/c/F.3d/592/602/","by":{"1":"18, 33"}},{"t":"case","label":"United States v. Burgos","cite":"137 F.3d 841","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/137/841/","by":{"1":"28, 29"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"United States v. Kelly-Tuorila","cite":"759 Fed. Appx. 236","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./759/236/","by":{"1":"5"}},{"t":"case","label":"United States v. Lucien","cite":"347 F.3d 45","y":2003,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/347/45/","by":{"1":"33","2":"18"}},{"t":"case","label":"United States v. Lumbard","cite":"706 F.3d 716","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/706/716/","by":{"1":"18"}},{"t":"case","label":"United States v. Oregon & California R.R.","cite":"164 U.S. 526","y":1896,"id":"scdb/1896-054","sc":1,"sum":"The grant of public land made to the Oregon Central Railroad Company by the act of May 4, 1870, c. 69, 16 Stat. 94, “ for the purpose of aiding in the construction of a railroad and telegraph line from Portland to Astoria and from a suitable point of junction near Forest Grove to the Yamhill River near McMinnville in the State of Oregon ” contemplated a main line from Portland to Astoria opening up to settlement …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"United States v. Osuna-Alvarez","cite":"788 F.3d 1183","y":2015,"url":"https://www.courtlistener.com/c/F.3d/788/1183/","by":{"1":"18"}},{"t":"case","label":"United States v. Ozuna-Cabrera","cite":"663 F.3d 496","y":2011,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/663/496/","by":{"1":"18"}},{"t":"case","label":"United States v. Perry","cite":"757 F.3d 166","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/757/166/","by":{"1":"33"}},{"t":"case","label":"United States v. Retana","cite":"641 F.3d 272","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/641/272/","by":{"1":"18"}},{"t":"case","label":"United States v. Reynolds","cite":"710 F.3d 434","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/710/434/","by":{"1":"18"}},{"t":"case","label":"United States v. Ruiz","cite":"698 Fed. Appx. 978","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./698/978/","by":{"1":"33"}},{"t":"case","label":"United States v. Skodnek","cite":"933 F. Supp. 1108","y":1996,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp./933/1108/","by":{"1":"28"}},{"t":"case","label":"United States v. Smith","cite":"756 F.3d 1179","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1179/","by":{"1":"11"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"United States v. Zitron","cite":"810 F.3d 1253","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/810/1253/","by":{"1":"19"}},{"t":"case","label":"Voisine v. United States","cite":"579 U.S. 686","y":2016,"id":"2015/14-10154","sc":1,"op":3,"sum":"The Court held that a reckless domestic violence assault qualifies as misdemeanor crime of domestic violence for the purpose of prohibiting firearm possession.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Wooden v. United States","cite":"142 S. Ct. 1063","y":2022,"id":"2021/20-5279","sc":1,"op":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31, 37","2":"22, 23"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"1":"2-4"}},{"t":"usc","label":"18 U.S.C. § 287","url":"https://www.law.cornell.edu/uscode/text/18/287","by":{"1":"16"}},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","by":{"1":"3"}},{"t":"usc","label":"18 U.S.C. § 499","url":"https://www.law.cornell.edu/uscode/text/18/499","by":{"1":"20"}},{"t":"usc","label":"18 U.S.C. § 913","url":"https://www.law.cornell.edu/uscode/text/18/913","by":{"1":"20"}},{"t":"usc","label":"18 U.S.C. § 915","url":"https://www.law.cornell.edu/uscode/text/18/915","by":{"1":"20"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)","(c)(1)(A)","(d)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"1":"11, 12, 35, 11, 11","2":"4"}},{"t":"usc","label":"18 U.S.C. § 1342","url":"https://www.law.cornell.edu/uscode/text/18/1342","by":{"1":"20"}},{"t":"usc","label":"18 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/18/1349","by":{"1":"2, 3"}},{"t":"usc","label":"18 U.S.C. § 1424","url":"https://www.law.cornell.edu/uscode/text/18/1424","by":{"1":"21"}},{"t":"usc","label":"42 U.S.C. § 1320a-7b","url":"https://www.law.cornell.edu/uscode/text/42/1320a-7b","subs":["(b)(2)"],"by":{"1":"16, 3"}},{"t":"rule","label":"Fed. R. Crim. P. 52","url":"https://www.law.cornell.edu/rules/frcrmp/rule_52","subs":["(b)"],"by":{"1":"6"}},{"t":"case","label":"Doe v. McMillan","cite":"412 U.S. 306","y":1973,"id":"1972/71-6356","sc":1,"sum":"Petitioners, parents of District of Columbia (D.bC.) school children, buught this action seeking damages and declaratory and injunctive relief for invasion of privacy'that they claimed resulted from ths dissemination of a congressional report on the D. C. school system that included identification of students in derogatory contexts. The named defendants included members of a House committee, Committee employees; a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"N.L.R.B. v. SW. Gen., Inc.","cite":"580 U.S. 288","y":2017,"url":"https://supreme.justia.com/cases/federal/us/580/288/","sc":1,"by":{"2":"14"}},{"t":"case","label":"N.Y. State Conf. of Blue Cross & Blue Shield Plans v. Travelers Ins. Co.","cite":"514 U.S. 645","y":1995,"id":"1994/93-1408","sc":1,"op":2,"sum":"New York's surcharge provisions do not \"relate to\" employee benefit plans within the meaning of § 514(a) and, thus, are not pre-empted.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"Stump v. Sparkman","cite":"435 U.S. 349","y":1978,"id":"1977/76-1750","sc":1,"sum":"The Court held that a district court judge has the power to entertain and act upon the petition for sterilization, which makes him immune from damages liability even if his approval of the petition was in error.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"United States v. Coffman","cite":"94 F.3d 330","y":1996,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/94/330/","by":{"2":"7"}},{"t":"case","label":"United States v. Kimble","cite":"2015 WL 4164820","y":2015,"court":"D. Md. July 8","by":{"2":"19"}},{"t":"case","label":"United States v. Spurgeon","cite":"117 F.3d 641","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/117/641/","by":{"2":"21"}},{"t":"case","label":"United States v. Stokes","cite":"392 Fed. Appx. 362","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./392/362/","by":{"2":"15"}},{"t":"case","label":"Zedner v. United States","cite":"547 U.S. 489","y":2006,"id":"2005/05-5992","sc":1,"sum":"The Supreme Court unanimously held that a defendant may not simply waive his right to a speedy trial under the Act. The list of acceptable reasons for an \"ends-of-justice\" order by the judge includes specific mention of the defendant's need for time to obtain counsel and prepare his case.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"usc","label":"15 U.S.C. § 6151","url":"https://www.law.cornell.edu/uscode/text/15/6151","by":{"2":"17"}},{"t":"usc","label":"29 U.S.C. § 1144","url":"https://www.law.cornell.edu/uscode/text/29/1144","subs":["(a)"],"by":{"2":"4"}},{"t":"usc","label":"42 U.S.C. § 1396d","url":"https://www.law.cornell.edu/uscode/text/42/1396d","subs":["(a)(31)(A)"],"by":{"2":"7"}},{"t":"usc","label":"47 U.S.C. § 227","url":"https://www.law.cornell.edu/uscode/text/47/227","by":{"2":"16"}},{"t":"reg","label":"16 C.F.R. § 310.4","url":"https://www.ecfr.gov/current/title-16/section-310.4","subs":["(b)(1)(iii)"],"by":{"2":"17"}}]};